const D = { energy:.65, scale:1, hue:320, groove:.6, limbs:.6, glow:.4, x:.5, y:.62, speed:1, density:.5, style:'disco', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const fr = i => { const s = Math.sin((i*12.9898 + P.seed*78.233)) * 43758.5453; return s - Math.floor(s); };
const sty=P.style, en=P.energy, t=K.t, dc=drawingContext;
const u=Math.min(width,height), sc=u*0.0042*P.scale, cx=P.x*width, cy=P.y*height;
const beat=t*(2.0+en*1.5)*P.speed;
// slow incommensurate groove drift so the pose never re-phases at 8s
const drift=(0.9*Math.sin(t*0.37)+0.5*Math.sin(t*0.83+1.5))*30*sc*(0.4+en);
const kick=K.pulse*0.4+A.bass*0.5;

let body=[0,0,8], accent=[P.hue,80,100], glow=false;
if(sty==='neon'){ body=[P.hue,80,60]; accent=[(P.hue+150)%360,90,100]; glow=true; }
else if(sty==='disco'){ body=[P.hue,70,55]; accent=[45,90,100]; }
else if(sty==='contemp'){ body=[P.hue,20,30]; accent=[P.hue,30,70]; }
else if(sty==='break'){ body=[210,15,20]; accent=[15,80,95]; }
function Cc(a,al){ return color(a[0],a[1],a[2],(al==null?100:al)*P.alpha/100); }
const outline=(sty==='neon');
function limb(x1,y1,x2,y2,w){ if(outline){ stroke(Cc(accent,90)); strokeWeight(w); } else { stroke(Cc(body,100)); strokeWeight(w);} line(x1,y1,x2,y2); }

// dance move selection (evolves slowly)
const move=Math.floor((t*0.12 + fr(2)*3)%3);   // 0 arms-up groove, 1 side-step, 2 spin/point

push();
translate(cx+drift, cy);
scale(sc);
noStroke(); fill(0,0,0,14); ellipse(0,96,110*(1+Math.abs(Math.sin(beat))*0.1),16);

const hipSway=Math.sin(beat)*18*P.groove;
const bounce=Math.abs(Math.sin(beat))*10*(0.5+en);
const shoulder=-bounce*0.5;
push(); translate(hipSway*0.5, -bounce);
strokeCap(ROUND); noFill();
// legs
const stepA=Math.sin(beat+ (move===1?1.5:0));
if(move===1){ limb(hipSway*0.3,10, hipSway*0.3-30-stepA*20, 78, 12); limb(hipSway*0.3,10, hipSway*0.3+30+stepA*20, 78, 12); }
else { limb(0,10, -14-stepA*10, 78, 12); limb(0,10, 14+stepA*10, 78-Math.max(0,stepA)*14, 12); }
// torso
limb(hipSway*0.4,10, shoulder*0+0,-52, 16);
// head
if(outline){ noFill(); stroke(Cc(accent,90)); strokeWeight(6); circle(0,-64,26);} else { fill(Cc(body,100)); noStroke(); circle(0,-64,26); }
noFill();
// arms — depends on move
const armT=Math.sin(beat*1.0)*P.limbs;
if(move===0){ // arms up
  limb(0,-46, -34, -76-Math.max(0,armT)*24, 11); limb(0,-46, 34, -76-Math.max(0,-armT)*24, 11);
} else if(move===1){ // side arms
  limb(0,-46, -44+armT*10, -40-armT*20, 11); limb(0,-46, 44+armT*10, -40+armT*20, 11);
} else { // point / spin
  limb(0,-46, 44*Math.cos(beat), -46+44*Math.sin(beat)*0.6, 11); limb(0,-46, -20, -20, 11);
}
pop();
// glow rim / sparkle
if(glow){ dc.save(); dc.shadowBlur=18; dc.shadowColor=Cc(accent,90).toString(); noStroke(); fill(Cc(accent,40)); circle(0,-40,6); dc.restore(); }
// a couple beat sparkles
if(sty==='disco'||sty==='neon'){ for(let i=0;i<4;i++){ const a=beat+i*1.6; const sx=Math.cos(a)*70, sy=-40+Math.sin(a)*50; fill(Cc(accent, 30+40*Math.max(0,Math.sin(beat*2+i)))); noStroke(); circle(sx,sy,3+kick*3); } }
blendMode(BLEND); dc.shadowBlur=0;
pop();
